/// Every Seat Gateway method in v1, in the spec's grouping. The enum is the
/// authority for the method list; `buf breaking` in WIRE_JSON mode makes a
/// silent rename or removal impossible.
///
/// Scope required per method is a separate table owned by the auth contract.
/// The scopes are: observe, plan, plan.submit, docs, spectate.nofog, admin.
/// Seat tokens can never hold spectate.nofog.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum Method {
    Unspecified = 0,
    // --- Status --------------------------------------------------------------

    /// "get_status" — phase, timers, and the coming segment's length from the
    /// frozen snapshot.
    GetStatus = 1,
    /// "wait_for" — long poll on a phase change or a feed digest.
    WaitFor = 2,
    // --- Memory --------------------------------------------------------------

    /// "save_notes" — the private seat notebook, 4,000 characters, returned at
    /// the top of get_briefing. Sits under the plan scope; the editor's notes box
    /// reaches it like any other editor feature. Never leaves the gateway for
    /// another seat.
    SaveNotes = 10,
    // --- Knowledge -----------------------------------------------------------

    /// "get_briefing" — the main one. Carries the notebook, the seat's displayed
    /// standing and the coming segment's length.
    GetBriefing = 20,
    /// "get_recap"
    GetRecap = 21,
    /// "list_beacons"
    ListBeacons = 22,
    /// "get_beacon"
    GetBeacon = 23,
    /// "get_map_summary"
    GetMapSummary = 24,
    /// "query_area" — NO REQUEST/RESPONSE PAIR YET, and that is deliberate: no
    /// skeleton client calls it. Its pair arrives with S3's knowledge store,
    /// which is what defines the area query's own salience budget.
    QueryArea = 25,
    /// "list_known_enemies" — no pair yet; arrives with S3's knowledge store,
    /// which is where "known" gets its reach-memory definition.
    ListKnownEnemies = 26,
    /// "get_reports" — no pair yet; arrives with S3's knowledge store, alongside
    /// the report kinds it returns.
    GetReports = 27,
    /// "get_economy_forecast" — $ and kW, with what-ifs.
    GetEconomyForecast = 28,
    /// "get_capabilities" — no pair yet; arrives with S4, which is the stage
    /// that introduces licences and therefore gives the method something to
    /// report.
    GetCapabilities = 29,
    /// "estimate_route"
    EstimateRoute = 30,
    // --- Docs ----------------------------------------------------------------

    /// "get_schema" — sliced to what the seat can use. Generated from the
    /// schema, so it cannot drift.
    GetSchema = 40,
    /// "list_templates"
    ListTemplates = 41,
    // --- Planning ------------------------------------------------------------

    /// "instantiate_template"
    InstantiateTemplate = 50,
    /// "verify_plan" — takes depth: quick | full, defaults to full. See
    /// VerifyPlan.Depth below.
    VerifyPlan = 51,
    /// "render_plan" — the plain-language rendering. Reads the coming segment's
    /// length from the frozen snapshot.
    RenderPlan = 52,
    /// "patch_plan" — applies the JSON Patch suggestions a report carries.
    PatchPlan = 53,
    /// "save_draft"
    SaveDraft = 54,
    /// "list_drafts"
    ListDrafts = 55,
    /// "get_safe_plan" — what the operator would file on a timeout, so a seat
    /// can see the cost of one (spec section 14).
    GetSafePlan = 56,
    // --- Commit --------------------------------------------------------------

    /// "submit_plan" — always runs FULL. The latest verified submission replaces
    /// the previous one, any number of times until the timer ends.
    SubmitPlan = 60,
    /// "set_ready"
    SetReady = 61,
    // --- During play ---------------------------------------------------------

    /// "get_segment_feed" — fog-filtered events (no-fog for every seat in casual
    /// matches) plus a digest for every 60 s of game time. Engine chatter rides
    /// the same feed as labelled one-way lines. Planning is closed during play
    /// and the recap.
    GetSegmentFeed = 70,
    /// "get_view" — the one read a camera needs: terrain chunks and the entities
    /// standing on them, as THIS viewer may see them. Cursor-driven: an empty
    /// cursor is a keyframe, any other cursor is "what changed since the view it
    /// came from". Every phase, because a Lull is watched as well as played.
    GetView = 71,
    // --- Match control -------------------------------------------------------
    //
    // The four methods the local lobby drives the match with. `admin` covers
    // lobby and match control (spec section 12) and can never read another
    // seat's playbooks, drafts or knowledge, so none of these four reports
    // anything about a seat beyond the one aggregate bit `report_host_clock`
    // answers.
    //
    // GAME MILLISECONDS ONLY. No tick and no state hash reaches the wire, here
    // or anywhere else: this file's transport note has said "times are game
    // milliseconds, never ticks" since T1, and a state hash handed to the human
    // seat's own process would be the whole world in eight bytes.

    /// "end_lull" — seal every seat's orders and open the Push. PHASE_CLOSED
    /// outside a Lull.
    EndLull = 90,
    /// "advance_push" — run the Push for a stretch of GAME time. PHASE_CLOSED
    /// outside a Push.
    AdvancePush = 91,
    /// "end_recap" — close the recap and open the next Lull. PHASE_CLOSED
    /// outside a recap.
    EndRecap = 92,
    /// "report_host_clock" — the host's own clock, reported to a gateway that
    /// has none. Valid in every phase that consumes no sim tick.
    ReportHostClock = 93,
}
